/**
 * Determines whether the payload is an error thrown by Axios
 *
 * @param {*} payload The value to test
 *
 * @returns {boolean} True if the payload is an error thrown by Axios, otherwise false
 */
export default function isAxiosError(payload) {
  return utils.isObject(payload) && (payload.isAxiosError === true);
}

import type { FPArity, FPFn, FPFnInput } from "../../types";

/**
 * Converts a function to a curried function that accepts arguments in reverse
 * order.
 *
 * @param fn - The function to convert to FP
 * @param arity - The arity of the function
 * @param curriedArgs - The curried arguments
 *
 * @returns FP version of the function
 *
 * @private
 */
export function convertToFP<Fn extends FPFnInput, Arity extends FPArity>(
  fn: Fn,
  arity: Arity,
  curriedArgs: unknown[] = [],
): FPFn<Fn, Arity> {
  return (
    curriedArgs.length >= arity
      ? fn(...curriedArgs.slice(0, arity).reverse())
      : (...args: unknown[]) => convertToFP(fn, arity, curriedArgs.concat(args))
  ) as FPFn<Fn, Arity>;
}

import { useState, useEffect } from 'react';
import { httpGet } from 'next-basics';
import enUS from '../../../public/intl/language/en-US.json';

const languageNames = {
  'en-US': enUS,
};

export function useLanguageNames(locale) {
  const [list, setList] = useState(languageNames[locale] || enUS);

  async function loadData(locale) {
    const { data } = await httpGet(`${process.env.basePath}/intl/language/${locale}.json`);

    if (data) {
      languageNames[locale] = data;
      setList(languageNames[locale]);
    } else {
      setList(enUS);
    }
  }

  useEffect(() => {
    if (!languageNames[locale]) {
      loadData(locale);
    } else {
      setList(languageNames[locale]);
    }
  }, [locale]);

  return list;
}

export default useLanguageNames;

